input.content:
.supportSection {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding-top: 28px;
  padding-bottom: 32px;
}

.supportShell {
  position: relative;
  width: 100%;
  max-width: 820px;
}

.supportGlow {
  position: absolute;
  inset: -24px;
  border-radius: 44px;
  background:
    radial-gradient(circle at 18% 18%, rgba(95, 134, 255, 0.18) 0%, transparent 34%),
    radial-gradient(circle at 82% 28%, rgba(255, 255, 255, 0.1) 0%, transparent 28%),
    radial-gradient(circle at 50% 100%, rgba(42, 211, 107, 0.14) 0%, transparent 40%);
  filter: blur(26px);
  opacity: 0.92;
  pointer-events: none;
}

.supportCard {
  position: relative;
  overflow: hidden;
  padding: 32px;
  border-radius: 36px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0.04) 24%, rgba(11, 13, 20, 0.8) 100%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.01));
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow:
    0 34px 100px rgba(0, 0, 0, 0.58),
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    inset 0 -1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(26px) saturate(140%);
  -webkit-backdrop-filter: blur(26px) saturate(140%);
}

.supportHeader {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.supportKicker {
  margin: 0 0 10px;
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(246, 247, 248, 0.52);
}

.supportTitle {
  margin: 0;
  font-size: clamp(32px, 4vw, 46px);
  line-height: 1.04;
  letter-spacing: -0.04em;
  font-weight: 520;
  color: rgba(255, 255, 255, 0.96);
}

.supportDescription {
  position: relative;
  z-index: 1;
  margin: 24px 0 28px;
  max-width: 640px;
  font-size: 17px;
  line-height: 1.7;
  color: rgba(246, 247, 248, 0.72);
}

.supportGrid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.supportItem {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 20px;
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0.03) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.supportLabel {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(246, 247, 248, 0.45);
}

.supportLink {
  color: rgba(246, 247, 248, 0.94);
  text-decoration: none;
  font-size: 18px;
  line-height: 1.5;
  letter-spacing: -0.02em;
  word-break: break-word;
}

.supportLink:hover {
  color: #ffffff;
  text-decoration: underline;
}

.supportGrid {
  grid-template-columns: 1fr;
}

.supportHeader {
  flex-direction: column;
}

.supportDescription {
  font-size: 16px;
}

.supportCard {
  padding: 24px;
  border-radius: 28px;
}

